comparison_examples.postgresql:
-- Cách viết 1:
SELECT * FROM items WHERE code LIKE 'ABC%';

-- Cách viết 2:
SELECT * FROM items WHERE code ~~ 'ABC%';

-- Cách viết 1:
SELECT * FROM users WHERE email ILIKE '%@domain.com';

-- Cách viết 2:
SELECT * FROM users WHERE email ~~* '%@domain.com';

comparison_examples.sqlserver:
-- Cách 1: Sử dụng Collation Case-Insensitive tường minh
SELECT * FROM products WHERE name LIKE '%laptop%' COLLATE Latin1_General_CI_AS;

-- Cách 2: Dùng LOWER() (lưu ý ảnh hưởng SARGable)
SELECT * FROM products WHERE LOWER(name) LIKE '%laptop%';

comparison_examples.postgresql:
SELECT department_id, string_agg(employee_name, '; ' ORDER BY hire_date ASC) AS emp_list
FROM employees
GROUP BY department_id;

comparison_examples.sqlserver:
SELECT department_id, STRING_AGG(employee_name, '; ') WITHIN GROUP (ORDER BY hire_date ASC) AS emp_list
FROM employees
GROUP BY department_id;

comparison_examples.postgresql:
SELECT id, payload ->> 'customer_code' AS cust_code
FROM orders
WHERE payload ->> 'status' = 'COMPLETED';

comparison_examples.sqlserver:
SELECT id, JSON_VALUE(payload, '$.customer_code') AS cust_code
FROM orders
WHERE JSON_VALUE(payload, '$.status') = 'COMPLETED';

comparison_examples.postgresql:
SELECT DISTINCT ON (customer_id) customer_id, order_id, order_date
FROM orders
ORDER BY customer_id, order_date DESC;

CREATE TEMP TABLE TempEmployees AS
SELECT id, name, salary
FROM employees WHERE salary > 50000;

comparison_examples.sqlserver:
SELECT id, name, salary
INTO #TempEmployees
FROM employees WHERE salary > 50000;

